1	//! 内部内存分配 API — 1:1 移植 `sqlite-source/src/malloc.c`。
2	//!
3	//! 公共契约(对齐 C 源码):
4	//! - `malloc(n)`: n<=0 → NULL;n>MAX → NULL;OOM → NULL,设置 `db.malloc_failed`
5	//! - `malloc64(n)`: n==0 → NULL;n>MAX → NULL;OOM → NULL,设置 `db.malloc_failed`
6	//! - `realloc(p, n)`: p==NULL 退化为 malloc;n==0 释放 p 返回 NULL;
7	//!   n>MAX 返回 NULL, p 保留;OOM 返回 NULL, p 保留(原指针永不丢失)
8	//! - `free(p)`: NULL no-op
9	//! - 所有分配保证 8 字节对齐(对齐 C 端 `EIGHT_BYTE_ALIGNMENT` 断言)
10	//!
11	//! 实现:基于 `std::alloc::Global` + 显式 `Layout`,通过全局 `Mutex<HashMap>`
12	//! 跟踪每块分配的 size(因为 Rust 的 `GlobalAlloc` 本身不提供 xSize hook)。
13	//! 这模拟了 C 端 `sqlite3GlobalConfig.m.xSize` 的角色。
14	
15	use std::alloc::{self, Layout};
16	use std::collections::HashMap;
17	use std::sync::{Mutex, OnceLock};
18	
19	use crate::handle::SqliteDb;
20	
21	/// SQLITE_MAX_ALLOCATION_SIZE = 2_147_483_391 — 见 `sqliteLimit.h:42`。
22	pub const SQLITE_MAX_ALLOCATION_SIZE: u64 = 2_147_483_391;
23	
24	/// 所有内部分配的对齐 — 对齐 C 端 `EIGHT_BYTE_ALIGNMENT` 宏(8 字节)。
25	const MALLOC_ALIGN: usize = 8;
26	
27	/// 全局分配 size 表(模拟 `sqlite3GlobalConfig.m.xSize`)。
28	///
29	/// `ptr_addr → size`。只在分配/释放时短暂持锁。
30	/// 用 `usize`(指针地址)作 key,避免 `*mut u8`/`NonNull<u8>` 的 `Send` 约束。
31	static ALLOC_SIZES: OnceLock<Mutex<HashMap<usize, usize>>> = OnceLock::new();
32	
33	#[inline]
34	fn sizes() -> &'static Mutex<HashMap<usize, usize>> {
35	    ALLOC_SIZES.get_or_init(|| Mutex::new(HashMap::new()))
36	}
37	
38	/// 内部 malloc 家族 — 对应 C 端 `sqlite3Malloc` / `sqlite3MallocZero` /
39	/// `sqlite3Realloc` / `sqlite3_free`。
40	///
41	/// `pub` 是为了让 `tests/util/alloc.rs` 的差分测试能直接调用;FFI 公开层
42	/// (`src/api.rs`)只是 thin wrapper。
43	pub struct Malloc;
44	
45	impl Malloc {
46	    /// `sqlite3Malloc(n)` — 分配 n 字节。
47	    ///
48	    /// C 行为(`malloc.c:296-309`):`n==0 || n>SQLITE_MAX_ALLOCATION_SIZE` → NULL;
49	    /// OOM → NULL,设置 `db.malloc_failed`。
50	    // 我们遵循内部 API 全部 safe 的约定(参 `02-c-porting-conventions.md` §2):
51	    // 返回的 `*mut u8` 仍是裸指针,但调用方在 `unsafe` 上下文中使用。
52	    // 抑制 `not_unsafe_ptr_arg_deref` lint。
53	    #[allow(clippy::not_unsafe_ptr_arg_deref)]
54	    pub fn malloc(n: u64, db: Option<&SqliteDb>) -> *mut u8 {
55	        if n == 0 || n > SQLITE_MAX_ALLOCATION_SIZE {
56	            return std::ptr::null_mut();
57	        }
58	        let size = n as usize;
59	        // SAFE: n > 0, align 是 2 的幂,from_size_align_unchecked 不会失败。
60	        let layout = unsafe { Layout::from_size_align_unchecked(size, MALLOC_ALIGN) };
61	        // SAFE: layout 合法;`alloc` 仅在 OOM 时返回 null,不 panic。
62	        let p = unsafe { alloc::alloc(layout) };
63	        if p.is_null() {
64	            if let Some(db) = db {
65	                db.set_malloc_failed();
66	            }
67	            return std::ptr::null_mut();
68	        }
69	        record_alloc(p, size);
70	        p
71	    }
72	
73	    /// `sqlite3Malloc64(n)` — 同 `malloc`,显式 i64/u64 签名。
74	    #[allow(clippy::not_unsafe_ptr_arg_deref)]
75	    pub fn malloc64(n: u64, db: Option<&SqliteDb>) -> *mut u8 {
76	        Self::malloc(n, db)
77	    }
78	
79	    /// `sqlite3MallocZero(n)` — alloc + memset 0。
80	    #[allow(dead_code)] // 后续子任务(sqlite3DbMallocZero)会接入
81	    #[allow(clippy::not_unsafe_ptr_arg_deref)]
82	    pub fn malloc_zero(n: u64, db: Option<&SqliteDb>) -> *mut u8 {
83	        let p = Self::malloc(n, db);
84	        if !p.is_null() {
85	            // SAFE: p 是合法的 n 字节分配,memset 0 不越界。
86	            unsafe { std::ptr::write_bytes(p, 0u8, n as usize) };
87	        }
88	        p
89	    }
90	
91	    /// `sqlite3Realloc(p, n)` — 调整 p 的大小。
92	    ///
93	    /// C 行为(`malloc.c:503-556`):
94	    /// - `p==NULL` → 退化为 `malloc(n)`
95	    /// - `n==0` → 释放 p,返回 NULL
96	    /// - `n>MAX` → 返回 NULL,**p 保留**
97	    /// - OOM → 返回 NULL,**p 保留**(C 永不释放失败时的原指针)
98	    #[allow(dead_code)] // 公开 API 转换在后续子任务(sqlite3_realloc)接入
99	    #[allow(clippy::not_unsafe_ptr_arg_deref)]
100	    pub fn realloc(p: *mut u8, n: u64, db: Option<&SqliteDb>) -> *mut u8 {
101	        if p.is_null() {
102	            return Self::malloc(n, db);
103	        }
104	        if n == 0 {
105	            Self::free(p);
106	            return std::ptr::null_mut();
107	        }
108	        if n > SQLITE_MAX_ALLOCATION_SIZE {
109	            return std::ptr::null_mut();
110	        }
111	        let old_size = match lookup_size(p) {
112	            Some(s) => s,
113	            // p 不是我们分配的(无法 resize) → 视为 OOM。
114	            None => {
