122	        // 分配新块;若 OOM,**保留 p**(对齐 C 行为)。
123	        let new_p = Self::malloc(n, db);
124	        if new_p.is_null() {
125	            return std::ptr::null_mut();
126	        }
127	        let copy_len = old_size.min(new_size);
128	        // SAFE: new_p 是 new_size 字节有效分配;src p 仍有效;copy_len 不越界任一方。
129	        unsafe { std::ptr::copy_nonoverlapping(p, new_p, copy_len) };
130	        // 释放旧块(不影响 new_p)。
131	        Self::free(p);
