1	//! `tests/util/alloc.rs` — 8 单元测试严格对齐 C `malloc.c` 行为。
2	//!
3	//! 这些测试直接调 `libsqlite_rs::Malloc` 内部 API(因为公开 FFI
4	//! 目前还没有 `sqlite3_realloc`)。等 sqlite3_realloc 公开后,可另外加
5	//! 一组走 FFI 的差分测试。
6	
7	use libsqlite_rs::{Malloc, SqliteDb, SQLITE_MAX_ALLOCATION_SIZE};
8	
9	// ============================================================================
10	// Test 1: malloc(0) 返回 NULL
11	// ============================================================================
12	#[test]
13	fn malloc_zero_returns_null() {
14	    let p = Malloc::malloc(0, None);
15	    assert!(p.is_null(), "malloc(0) must return NULL per malloc.c:320");
16	}
17	
18	// ============================================================================
19	// Test 2: malloc64(0) 返回 NULL
20	// ============================================================================
21	#[test]
22	fn malloc64_zero_returns_null() {
23	    let p = Malloc::malloc64(0, None);
24	    assert!(p.is_null(), "malloc64(0) must return NULL per malloc.c:298");
25	}
26	
27	// ============================================================================
28	// Test 3: free(NULL) 是 no-op
29	// ============================================================================
30	#[test]
31	fn free_null_is_noop() {
32	    // 不能 panic,也不能修改 malloc_failed 标志
33	    Malloc::free(std::ptr::null_mut());
34	    Malloc::free(std::ptr::null_mut());
35	}
36	
37	// ============================================================================
38	// Test 4: realloc 失败时原指针保留
39	// ============================================================================
40	#[test]
41	fn realloc_failure_preserves_original_pointer() {
42	    // 1) 分配 64 字节
43	    let p = Malloc::malloc(64, None);
44	    assert!(!p.is_null());
45	
46	    // 2) 用超过 SQLITE_MAX_ALLOCATION_SIZE 的 size realloc → 失败
47	    let r = Malloc::realloc(p, SQLITE_MAX_ALLOCATION_SIZE + 1, None);
48	    assert!(r.is_null(), "realloc with n>MAX must return NULL per malloc.c:515-517");
49	
50	    // 3) p 必须仍然有效 — 写一个字节再读
51	    // SAFE: p 是 64 字节有效分配,未释放。
52	    unsafe { std::ptr::write_bytes(p, 0x42, 64) };
53	    let byte0 = unsafe { *p };
54	    assert_eq!(byte0, 0x42, "original p must still be writable after failed realloc");
55	
56	    // 清理
57	    Malloc::free(p);
58	}
59	
60	// ============================================================================
61	// Test 5: 大块 alloc — 超过 MAX 必须被拒绝
62	// ============================================================================
63	#[test]
64	fn large_alloc_above_max_is_rejected() {
65	    let p = Malloc::malloc(SQLITE_MAX_ALLOCATION_SIZE + 1, None);
66	    assert!(p.is_null(), "alloc > SQLITE_MAX_ALLOCATION_SIZE must fail");
67	
68	    // 边界值 0 同样被拒
69	    let p2 = Malloc::malloc_zero(SQLITE_MAX_ALLOCATION_SIZE + 1, None);
70	    assert!(p2.is_null(), "malloc_zero > MAX must also return NULL");
71	
72	    // 合法的大块(避开触发 OOM killer,只用 1MB 做"大"测试)
73	    let big = Malloc::malloc(1024 * 1024, None);
74	    assert!(!big.is_null(), "1MB alloc must succeed");
75	    Malloc::free(big);
76	}
77	
78	// ============================================================================
79	// Test 6: 对齐 — 所有分配必须 8 字节对齐(对齐 EIGHT_BYTE_ALIGNMENT 断言)
80	// ============================================================================
81	#[test]
82	fn allocation_is_8_byte_aligned() {
83	    for size in [1, 3, 7, 8, 9, 15, 16, 17, 31, 32, 33, 127, 128, 1023, 1024] {
84	        let p = Malloc::malloc(size, None);
85	        assert!(!p.is_null(), "alloc of {size} bytes must succeed");
86	        assert_eq!(
87	            p as usize % 8,
88	            0,
89	            "alloc of {size} bytes must be 8-byte aligned, got {:#x}",
90	            p as usize
91	        );
92	        Malloc::free(p);
93	    }
94	}
95	
96	// ============================================================================
97	// Test 7: OOM 标志读写 — malloc 失败必须写 db.malloc_failed
98	// ============================================================================
99	#[test]
100	fn oom_flag_written_on_size_limit() {
101	    let db = SqliteDb::new();
102	    assert!(!db.check_malloc_failed(), "malloc_failed must start false");
103	
104	    // 触发"参数超限"路径:C 端对 n>MAX **不**写 malloc_failed(因为是
105	    // 参数错误,不是真正的 OOM)。我们改用 malloc_zero 测真实 OOM 写入
106	    // — 但 64 位下没法稳定触发 alloc 失败,所以这条主要验证:
107	    //  a) 超限不 panic
108	    //  b) 标志状态与输入一致
109	    let p = Malloc::malloc(SQLITE_MAX_ALLOCATION_SIZE + 1, Some(&db));
110	    assert!(p.is_null());
111	    // 超限不写 malloc_failed(对齐 C 端 sqlite3Malloc:写 0 走参数检查)
112	    assert!(
113	        !db.check_malloc_failed(),
114	        "size > MAX is a parameter error, not OOM — C does not set malloc_failed"
115	    );
116	
117	    // 正常 alloc 不写标志
118	    let q = Malloc::malloc(64, Some(&db));
119	    assert!(!q.is_null());
120	    assert!(!db.check_malloc_failed());
121	    Malloc::free(q);
122	
123	    // 手动置位,验证 read 路径
124	    db.set_malloc_failed();
125	    assert!(db.check_malloc_failed());
126	}
127	
128	// ============================================================================
129	// Test 8: 0 字节 realloc — 必须释放 p,返回 NULL
130	// ============================================================================
131	#[test]
132	fn realloc_with_zero_size_frees_and_returns_null() {
133	    let p = Malloc::malloc(128, None);
134	    assert!(!p.is_null());
135	
136	    let r = Malloc::realloc(p, 0, None);
137	    assert!(r.is_null(), "realloc(p, 0) must return NULL per malloc.c:511-514");
138	    // p 已经被 free,后续 free(p) 必须是 no-op(查表时找不到条目)
139	    // 二次 free 不应 panic
140	    // (不能直接 free 同一指针两次 — 内部会查表,未知指针就静默 no-op)
141	    Malloc::free(p);
142	}
