#[test]
fn write_read_roundtrip() {
    for &c in &[0x00u32, 0x41, 0x7F, 0x80, 0xA0, 0x7FF, 0x800, 0xFFF, 0xFFFF, 0x10000, 0x1F600, 0x10FFFF] {
        let mut buf = [0u8; 4];
        let n = utf8_write(&mut buf, c, 4);
        assert!(n >= 1 && n <= 4, "c={c:x} n={n}");
        let (decoded, n2) = utf8_read(&buf[..n]);
        // FFFD is the only value that may flip on roundtrip (e.g. c=0
        // with no continuation bytes decodes as 0, but c=0x80 should
        // roundtrip exactly). For valid codepoints, decoded == c.
        if (0xD800..=0xDFFF).contains(&c) || c == 0xFFFE || c == 0xFFFF {
            assert_eq!(decoded, 0xFFFD, "surrogate/FFFE c={c:x}");
        } else {
            assert_eq!(decoded, c, "roundtrip c={c:x}");
        }
        assert_eq!(n, n2);
    }
}

